DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT145-S2-Q9$batch13$ AND q.stimulus=$batch13$Columnist: Video games are not works of art. No matter how rich the aesthetic experience produced by a video game might be, it is interactive: players make choices that affect the outcome of the game. For something to be a work of art, it must produce an aesthetic experience that is controlled by the artist or artists who created the work.$batch13$ AND q.prompt=$batch13$The conclusion of the columnist's argument can be properly drawn if which one of the following is assumed?$batch13$ AND q.correct_choice=$batch13$B$batch13$) THEN RAISE EXCEPTION 'Question changed: PT145-S2-Q9'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanation_steps s WHERE s.explanation_id=$batch13$b5d69c6d-f840-4e89-a511-92ad114414af$batch13$) <> 0 OR (SELECT COUNT(*) FROM lr_explanation_choice_notes n WHERE n.explanation_id=$batch13$b5d69c6d-f840-4e89-a511-92ad114414af$batch13$) <> 5 THEN RAISE EXCEPTION 'Explanation changed: PT145-S2-Q9'; END IF; END $guard$;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e CROSS JOIN (VALUES (0, $batch13$Conclusion$batch13$, $batch13$Video games are not works of art.$batch13$), (1, $batch13$Evidence$batch13$, $batch13$Video games are interactive: players' choices affect the outcome. For something to be a work of art, it must produce an aesthetic experience controlled by the artists who created it.$batch13$), (2, $batch13$Evaluate$batch13$, $batch13$The rule says art requires an experience the creators control. The fact says games are interactive. Those connect only if an interactive experience can't be one the creators control. Supply that link and the conclusion follows.$batch13$), (3, $batch13$Goal$batch13$, $batch13$An interactive aesthetic experience isn't controlled by its creators.$batch13$)) v(position,label,body) WHERE e.id=$batch13$b5d69c6d-f840-4e89-a511-92ad114414af$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
